package com.api.validation;

/**
 * Policy model that decides which optional validations run for a response scenario:
 * the error-schema validation and the "Allow" header validation.
 *
 * The decision depends on the scenario (its status code context): for example the body of a
 * 404 generated by the server's routing is not defined by the API contract, so it has no
 * schema to validate. Create a policy only through the factory methods below.
 */
public class SchemaAndAllowHeaderValidationPolicy {

	// These fields are intentionally instance fields, NOT static.
	//
	// Each scenario in the DataProvider creates its own policy object
	// (e.g. one for "413 Oversized Payload", another for "401 Missing Auth", etc.),
	// and each of these objects needs to carry its OWN independent values:
	// a different schemaPath, a different reason, different flags.
	//
	// If these fields were static, there would be only ONE shared copy across
	// the entire class, regardless of how many policy objects are created.
	// Every new policy built by the DataProvider would silently overwrite the
	// previous one's values, so by the time all the scenarios are built, every
	// single one of them would end up pointing at whatever schemaPath/reason was
	// set LAST, not the one it was actually built with.
	//
	// This would not throw a NullPointerException even if accessed through a
	// null reference (e.g. someObject.schemaPath where someObject is null),
	// because static field access in Java is resolved at compile-time based on
	// the reference's declared type, not the actual instance. So the bug would
	// stay completely silent: tests would validate against the wrong schema
	// with no exception, no stack trace, and no obvious sign of what went wrong.
	//
	// Keeping these as instance fields (and "final", so they can never be
	// reassigned after construction) guarantees each SchemaAndAllowHeaderValidationPolicy
	// object is independent and immutable, exactly what a per-scenario configuration
	// object needs to be.

	// true = the error/success schema of the response is validated.
	public final boolean validateSchema;

	// true = the "Allow" header validation is requested. The header is required for 405 only.
	public final boolean validateAllowHeader;

	// Classpath location of the JSON schema. Required when validateSchema is true, otherwise null.
	public final String schemaPath;

	// Why this policy was chosen. It is shown in the console, in the Allure report
	// and in the message of a failed assertion.
	public final String reason;

	// Private: create a policy only through the factory methods below.
	private SchemaAndAllowHeaderValidationPolicy(boolean validateSchema, boolean validateAllowHeader,
			String schemaPath, String reason) {
		if (validateSchema && (schemaPath == null || schemaPath.isBlank())) {
			throw new IllegalArgumentException(
					"schemaPath is required when validateSchema is true. Reason was: " + reason);
		}
		this.validateSchema = validateSchema;
		this.validateAllowHeader = validateAllowHeader;
		this.schemaPath = schemaPath;
		this.reason = reason;
	}

	// General factory. Prefer the named factory methods below; they say what the policy is for.
	public static SchemaAndAllowHeaderValidationPolicy of(boolean validateSchema, boolean validateAllowHeader,
			String schemaPath, String reason) {
		return new SchemaAndAllowHeaderValidationPolicy(validateSchema, validateAllowHeader, schemaPath, reason);
	}

	// Validates the response schema only. The "Allow" header is not validated.
	// Use it for a response whose body the API contract defines
	// (for example 200, 401, 403, 415, 422).
	public static SchemaAndAllowHeaderValidationPolicy validateSchemaOnly(String schemaPath, String reason) {
		return of(true, false, schemaPath, reason);
	}

	// Skips BOTH optional validations: the schema validation and the "Allow" header validation.
	// Use it for a response that the server or the gateway generates, not the API contract
	// (for example 413 Payload Too Large or 404 Not Found): its response body is not defined by the contract,
	// and the "Allow" header is required only for 405, so there is nothing to validate.
	// "reason" says why the validation is skipped. It is shown in:
	//   - the console (the "Schema validation skipped ..." line),
	//   - the Allure report: the test Parameters and the "DataProvider Row Details" attachment,
	//   - the message of a failed assertion.
	public static SchemaAndAllowHeaderValidationPolicy skipSchemaAndAllowHeaderValidation(String reason) {
		return of(false, false, null, reason);
	}

	// Validates ONLY the "Allow" header (required for 405). The schema is not validated,
	// because the body of a 405 response is not defined by the contract.
	public static SchemaAndAllowHeaderValidationPolicy validateAllowHeaderOnly(String reason) {
		return of(false, true, null, reason);
	}

	// Validates both the response schema and the "Allow" header.
	public static SchemaAndAllowHeaderValidationPolicy validateSchemaAndAllowHeader(String schemaPath, String reason) {
		return of(true, true, schemaPath, reason);
	}

	/**
	 * The default "toString()" method in the "Object" class
	 * returns a memory hash (e.g., SchemaAndAllowHeaderValidationPolicy@3d4eac69).
	 * This overridden toString() returns a human-readable string representation
	 * of the object which is easy for logging and test failure analysis.
	 *
	 * With this override:
	 * - TestNG automatically calls toString() on assertion failures to display clear instance field values.
	 * - Logging frameworks like Log4j can directly capture the object's instance field values in logs.
	 */
	@Override
	public String toString() {
		return String.format(
				"SchemaAndAllowHeaderValidationPolicy{schema=%s, schemaPath='%s', allowHeader=%s, reason='%s'}",
				validateSchema, schemaPath, validateAllowHeader, reason);
	}
}
